// Selenium HTTPS Verification Test (Java)
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.junit.Test;
import static org.junit.Assert.*;

public class HttpsVerificationTest {

    @Test
    public void testHttpsEnabled() {
        WebDriver driver = new ChromeDriver();

        // Test HTTPS access
        driver.get("https://yourdomain.com");
        String currentUrl = driver.getCurrentUrl();
        assertTrue("URL should use HTTPS", currentUrl.startsWith("https://"));

        // Test HTTP redirect
        driver.get("http://yourdomain.com");
        currentUrl = driver.getCurrentUrl();
        assertTrue("HTTP should redirect to HTTPS", currentUrl.startsWith("https://"));

        driver.quit();
    }

    @Test
    public void testNoMixedContent() {
        ChromeOptions options = new ChromeOptions();
        options.setCapability(CapabilityType.ACCEPT_INSECURE_CERTS, false);
        WebDriver driver = new ChromeDriver(options);

        driver.get("https://yourdomain.com");

        // Check console for mixed content warnings
        LogEntries logs = driver.manage().logs().get(LogType.BROWSER);
        for (LogEntry entry : logs) {
            assertFalse("Mixed content detected: " + entry.getMessage(),
                entry.getMessage().toLowerCase().contains("mixed content"));
        }

        driver.quit();
    }
}
